 }

 void CanvasItemMaterial::flush_changes() {
-	MutexLock lock(material_mutex);
+	LocalVector<CanvasItemMaterial *> dirty_materials_to_process; // Make a copy of pending list, shader update can cause more materials to go dirty and deadlock.
+	{
+		MutexLock lock(material_mutex);
+
+		while (dirty_materials.first()) {
+			dirty_materials_to_process.push_back(dirty_materials.first()->self());
+			dirty_materials.first()->remove_from_list();
+		}
+	}

-	while (dirty_materials.first()) {
-		dirty_materials.first()->self()->_update_shader();
-		dirty_materials.first()->remove_from_list();
+	for (CanvasItemMaterial *E : dirty_materials_to_process) {
+		E->_update_shader();
 	}
+	dirty_materials_to_process.clear();
 }

